#include <iostream>
#include <iomanip>

class Ellipsoid {
private:
    double r1, r2, r3;
    static const double PI;
public:
    // 构造函数，带默认值
    Ellipsoid(double r1 = 1.0, double r2 = 1.0, double r3 = 1.0)
        : r1(r1), r2(r2), r3(r3) {}

    // 重载==运算符
    bool operator==(const Ellipsoid &other) const {
        return (r1 == other.r1 && r2 == other.r2 && r3 == other.r3);
    }

    // 计算体积 V = 4*PI*r1*r2*r3/3
    double GetVolume() const {
        return 4.0 * PI * r1 * r2 * r3 / 3.0;
    }
};

// 类外初始化静态常量成员
const double Ellipsoid::PI = 3.1416;

int main() {
    double a1, a2, a3, b1, b2, b3;
    std::cin >> a1 >> a2 >> a3;
    std::cin >> b1 >> b2 >> b3;

    Ellipsoid e1(a1, a2, a3);
    Ellipsoid e2(b1, b2, b3);

    // 输出体积，保留3位小数
    std::cout << std::fixed << std::setprecision(3);
    std::cout << e1.GetVolume() << ", " << e2.GetVolume() << std::endl;

    // 判断是否相同
    if (e1 == e2) {
        std::cout << "The 1st ellipsoid is exactly the same as the 2nd one" << std::endl;
    } else {
        std::cout << "The 1st ellipsoid is different from the 2nd one" << std::endl;
    }

    return 0;
}

#include <iostream>

// 抽象基类
class Humanoid {
public:
    virtual void SayHello() = 0; // 纯虚函数
    virtual ~Humanoid() {}       // 虚析构函数
};

// 矮人类
class Dwarf : public Humanoid {
public:
    void SayHello() override {
        std::cout << "Hi, I am a dwarf." << std::endl;
    }
};

// 精灵类
class Elf : public Humanoid {
public:
    void SayHello() override {
        std::cout << "Hi, I am an elf." << std::endl;
    }
};

// 兽人类
class Orc : public Humanoid {
public:
    void SayHello() override {
        std::cout << "Hi, I am an orc." << std::endl;
    }
};

int main() {
    int n;
    std::cin >> n;

    // 动态分配基类指针数组
    Humanoid **arr = new Humanoid*[n];

    for (int i = 0; i < n; i++) {
        char type;
        std::cin >> type;
        if (type == 'D') {
            arr[i] = new Dwarf();
        } else if (type == 'E') {
            arr[i] = new Elf();
        } else if (type == 'O') {
            arr[i] = new Orc();
        }
    }

    // 多态调用
    for (int i = 0; i < n; i++) {
        arr[i]->SayHello();
    }

    // 释放内存
    for (int i = 0; i < n; i++) {
        delete arr[i];
    }
    delete[] arr;

    return 0;
}

#include <iostream>

class Circle {
private:
    double x, y; // 圆心坐标
    double r;    // 半径
public:
    static const double PI; // 公有静态常量

    // 构造函数，默认原点单位圆
    Circle(double x = 0.0, double y = 0.0, double r = 1.0)
        : x(x), y(y), r(r) {}

    // 计算周长
    double perimeter() const {
        return 2 * PI * r;
    }

    // 计算面积
    double area() const {
        return PI * r * r;
    }

    // 输出信息
    void print() const {
        std::cout << "Center: (" << x << ", " << y << ")" << std::endl;
        std::cout << "Radius: " << r << std::endl;
        std::cout << "Perimeter: " << perimeter() << std::endl;
        std::cout << "Area: " << area() << std::endl;
    }
};

// 类外初始化静态常量
const double Circle::PI = 3.1416;

int main() {
    double x, y, r;
    std::cin >> x >> y >> r;

    Circle c(x, y, r);
    c.print();

    return 0;
}

