    friend std::istream &operator>>(std::istream &is, Holiday &h) {
        is >> h.year >> h.month >> h.day;
        return is;
    }

    // 重载<< (友元)
    friend std::ostream &operator<<(std::ostream &os, const Holiday &h) {
