#include <iostream>

class CFraction {
    int num; // 分子
    int den; // 分母
public:
    CFraction(int n = 0, int d = 1) : num(n), den(d) {}

    // 重载>>
    friend std::istream &operator>>(std::istream &in, CFraction &fr) {
        in >> fr.num >> fr.den;
        return in;
    }

    // 重载<<
    friend std::ostream &operator<<(std::ostream &out, const CFraction &fr) {
        out << fr.num << "/" << fr.den;
        return out;
    }

    // 重载+
    CFraction operator+(const CFraction &other) const {
        return CFraction(num * other.den + den * other.num, den * other.den);
    }

    // 重载-
    CFraction operator-(const CFraction &other) const {
        return CFraction(num * other.den - den * other.num, den * other.den);
    }

    // 重载>
    bool operator>(const CFraction &other) const {
        CFraction tmp = *this - other;
        return (tmp.num * tmp.den > 0);
    }

    // 重载<
    bool operator<(const CFraction &other) const {
        CFraction tmp = *this - other;
        return (tmp.num * tmp.den < 0);
    }
};

int main() {
    CFraction f1, f2;
    std::cin >> f1 >> f2;
    std::cout << "A+B:" << (f1 + f2) << std::endl;
    std::cout << "A-B:" << (f1 - f2) << std::endl;
    std::cout << "A>B:" << std::boolalpha << (f1 > f2) << std::endl;
    std::cout << "A<B:" << std::boolalpha << (f1 < f2) << std::endl;
    return 0;
}

