// 冒泡排序函数模板，增加了对比较次数和数据移动次数的统计
template <typename T>
void bubble_sort(T *items, int count) {
    int a, b;
    int number_compare = 0;
    int number_move = 0;
    T t;
    for (a = 1; a < count; a++) {
        for (b = count - 1; b >= a; b--) {
            number_compare++;
            if (items[b - 1] > items[b]) {
                number_move++;
                t = items[b - 1];
                items[b - 1] = items[b];
                items[b] = t;
            }
        }
    }
    cout << "比较次数：" << number_compare << endl;
    cout << "移动次数：" << number_move << endl;
}

int main() {
    int arr[] = {5, 3, 1, 4, 2};
    int n = sizeof(arr) / sizeof(arr[0]);
    bubble_sort(arr, n);
    cout << "排序后的数组：";
    for (int i = 0; i < n; i++) {
        cout << arr[i] << " ";
    }
    cout << endl;
    return 0;
}

#include <iostream>
#include <cmath>

using std::cout;
using std::endl;

class Cuboid {
private:
    double L, W, H;
public:
    // 构造函数，使用初始化列表和默认参数
    Cuboid(double l = 1.0, double w = 1.0, double h = 1.0) : L(l), W(w), H(h) {}

    // 获取体积
    double GetVolume() const {
        return L * W * H;
    }

    // 判断两个长方体是否完全相同（浮点数比较建议使用极小值阈值，或者直接比较）
    bool IsEqual(const Cuboid &other) const {
        const double EPSILON = 1e-9;
        return (std::abs(L - other.L) < EPSILON) && 
               (std::abs(W - other.W) < EPSILON) && 
               (std::abs(H - other.H) < EPSILON);
    }
};

int main() {
    Cuboid c1; // 默认值 1, 1, 1
    Cuboid c2(2.0, 3.0, 4.0);
    Cuboid c3(2.0, 3.0, 4.0);

    cout << "c1的体积：" << c1.GetVolume() << endl; // 1.0
    cout << "c2的体积：" << c2.GetVolume() << endl; // 24.0
    cout << "c2与c3是否相同：" << (c2.IsEqual(c3) ? "相同" : "不同") << endl; // 相同
    cout << "c1与c2是否相同：" << (c1.IsEqual(c2) ? "相同" : "不同") << endl; // 不同
    return 0;
}

