// 抽象基类 Zombie
class Zombie {
protected:
    int hp;
    double speed;
    string name;
public:
    Zombie(int h, double s, string n) : hp(h), speed(s), name(n) {}
    virtual ~Zombie() { cout << "~Zombie " << name << endl; } // 必须包含虚析构函数

    virtual void talk() = 0;   // 纯虚函数
    virtual void freeze() = 0; // 纯虚函数

    void ShowInfo() const {
        cout << name << " - 生命值: " << hp << ", 速度: " << speed << endl;
    }
};

class OrdinaryZombie : public Zombie {
public:
    OrdinaryZombie(int h, double s) : Zombie(h, s, "普通僵尸") {}
    void talk() override { cout << "brains~~~" << endl; }
    void freeze() override { speed *= 0.5; cout << "普通僵尸被冻结，速度减半" << endl; }
};

class RoadblockZombie : public Zombie {
public:
    RoadblockZombie(int h, double s) : Zombie(h, s, "路障僵尸") {}
    void talk() override { cout << "brains~~~ 有个路障在头上！" << endl; }
    void freeze() override { speed *= 0.8; cout << "路障僵尸减速20%" << endl; }
};

class MetalBucketZombie : public Zombie {
public:
    MetalBucketZombie(int h, double s) : Zombie(h, s, "铁桶僵尸") {}
    void talk() override { cout << "brains~~~ 头顶上有个铁桶！" << endl; }
    void freeze() override { speed *= 0.4; cout << "铁桶僵尸减速60%" << endl; }
};

class NewspaperZombie : public Zombie {
public:
    NewspaperZombie(int h, double s) : Zombie(h, s, "读报僵尸") {}
    void talk() override { cout << "我在读报纸..." << endl; }
    void freeze() override { speed *= 0.5; cout << "读报僵尸减速50%" << endl; }
};

int main() {
    OrdinaryZombie Z1(100, 10.0);
    RoadblockZombie Z2(150, 8.0);
    MetalBucketZombie Z3(200, 6.0);
    NewspaperZombie Z4(120, 12.0);

    Zombie* zombies[] = { &Z1, &Z2, &Z3, &Z4 };
    int n = sizeof(zombies) / sizeof(zombies[0]);

    cout << "--- 僵尸群正在逼近 ---" << endl;
    for (int i = 0; i < n; i++) {
        zombies[i]->ShowInfo();
        zombies[i]->talk();
    }

    cout << "--- 寒冰射手发动攻击，僵尸群受冻 ---" << endl;
    for (int i = 0; i < n; i++) {
        zombies[i]->freeze();
        zombies[i]->ShowInfo();
    }
    return 0;
}

#include <iostream>

using std::cin;
using std::cout;
using std::endl;

template <typename T>
class Data {
private:
    T data[3];
public:
    Data() {
        cout << "请输入3个数据：" << endl;
        for (int i = 0; i < 3; i++) {
            cin >> data[i];
        }
    }
    T getMin() const; // 类体内声明
};

// 类外定义类模板的成员函数
template <typename T>
T Data<T>::getMin() const {
    T min_val = data[0];
    for (int i = 1; i < 3; i++) {
        if (data[i] < min_val) {
            min_val = data[i];
        }
    }
    return min_val;
}

int main() {
    Data<int> intData;
    cout << "最小值是：" << intData.getMin() << endl;

    Data<double> doubleData;
    cout << "极小值是：" << doubleData.getMin() << endl;
    return 0;
}

#include <iostream>
#include <fstream>
#include <vector>
#include <algorithm>
#include <sstream>
#include <iomanip>

using std::cout;
using std::endl;
using std::vector;
using std::ofstream;
using std::ostringstream;
using std::fixed;
using std::setprecision;

int main() {
    vector<double> prices = {10.0, 20.0, 30.0};
    const double taxRate = 0.05;
    double total = 0.0;
    ostringstream oss; // 使用 ostringstream 格式化拼接数据

    oss << fixed << setprecision(2);
    oss << "商品价格列表（加收 5% 税率）：" << endl;

    // 使用 std::for_each 与 Lambda 表达式，按引用捕获外部变量
    std::for_each(prices.begin(), prices.end(), [&total, taxRate, &oss](double price) {
        double taxedPrice = price * (1.0 + taxRate);
        total += taxedPrice;
        oss << "商品原价: " << price << " 元 -> 实付价格: " << taxedPrice << " 元" << endl;
    });

    oss << "总计实付金额：" << total << " 元" << endl;

    // 输出到控制台
    cout << oss.str();

    // 输出到文件 price.txt
    ofstream outFile("price.txt");
    if (outFile) {
        outFile << oss.str();
        outFile.close();
        cout << "数据已成功保存到 price.txt" << endl;
    } else {
        std::cerr << "打开文件 price.txt 失败！" << endl;
    }
    return 0;
}
